using UnityEditor;using UnityEngine;public sealed class AssetImport:AssetPostprocessor {void OnPreprocessTexture(){if(!assetPath.Contains("Resources/Art/"))return;var t=(TextureImporter)assetImporter;t.textureType=TextureImporterType.Default;t.alphaIsTransparency=true;t.mipmapEnabled=false;t.textureCompression=TextureImporterCompression.Uncompressed;t.maxTextureSize=2048;t.filterMode=FilterMode.Bilinear;}void OnPreprocessAudio(){if(!assetPath.Contains("Resources/Audio/"))return;var t=(AudioImporter)assetImporter;var s=t.defaultSampleSettings;s.loadType=assetPath.Contains("music")?AudioClipLoadType.Streaming:AudioClipLoadType.DecompressOnLoad;s.compressionFormat=AudioCompressionFormat.Vorbis;s.quality=.85f;t.defaultSampleSettings=s;}}